function tiling() {
	let columns = 20;
	let rows = 20;
	let cellW = (width) / columns;
	let cellH = (height) / rows;
	let emp = columns * rows;
	let grids = [];
	let rects = [];

	for (let j = 0; j < columns; j++) {
		let arr = []
		for (let i = 0; i < rows; i++) {
			arr[i] = false;
		}
		grids[j] = arr;
	}

	while (emp > 0) {
		let w = random([1, 2]);
		let h = w;
		let x = int(random(columns - w + 1));
		let y = int(random(rows - h + 1));
		let lap = true;
		for (let j = 0; j < h; j++) {
			for (let i = 0; i < w; i++) {
				if (grids[x + i][y + j]) {
					lap = false;
					break;
				}
			}
		}

		if (lap) {
			for (let j = 0; j < h; j++) {
				for (let i = 0; i < w; i++) {
					grids[x + i][y + j] = true;
				}
			}
			let xx = x * cellW;
			let yy = y * cellH;
			let ww = w * cellW;
			let hh = h * cellH;
			rects.push({
				x: xx + ww / 2,
				y: yy + hh / 2,
				w: ww,
				h: hh,
			});
			emp -= w * h;
		}
	}
	for (let i = 0; i < rects.length; i++) {
		let r = rects[i];
		let shapeType = int(random(9));
		let clr = random(colors);
		drawShape(r.x, r.y, r.w, shapeType, clr);
	}
}


