function checkered(x, y, w, cellCount) {
	let cellSize = w / cellCount;
	for (let i = 0; i < cellCount; i++) {
		for (let j = 0; j < cellCount; j++) {
			let cellX = i * cellSize + (cellSize / 2) + x - (w / 2);
			let cellY = j * cellSize + (cellSize / 2) + y - (w / 2);
			if ((i + j) % 2 == 0) {
				square(cellX, cellY, cellSize);
			}
		}
	}
}

function tiltStripe(x, y, w, count, clr) {
	let ww = w * sqrt(2);
	let breadth = ww / count;
	push();
	translate(x, y);
	noFill();
	square(0, 0, w);
	ctx.clip();
	fill(clr);
	rotate(PI / 4);
	for (let i = 0; i < count; i++) {
		let position = map(i, 0, count, 0, ww) - (ww / 2) + (breadth / 2);
		if (i % 2 == 0) {
			rect(x + position, y, breadth, ww);
		}
	}
	pop();
}

function stripe(x, y, w, count) {
	let breadth = w / count;

	for (let i = 0; i < count; i++) {
		let position = map(i, 0, count, 0, w) - (w / 2) + (breadth / 2);
		if (i % 2 == 0) {
			rect(x + position, y, breadth, w);
		}
	}
}

function polkaDot(x, y, w, cellCount) {
	let cellSize = w / cellCount;
	for (let i = 0; i < cellCount; i++) {
		for (let j = 0; j < cellCount; j++) {
			let cellX = i * cellSize + (cellSize / 2) + x - (w / 2);
			let cellY = j * cellSize + (cellSize / 2) + y - (w / 2);
			circle(cellX, cellY, cellSize / 2);
		}
	}
}

